-- Jeździectwo (ujeżdżenie, WKKW, skoki), szermierka i flag football – tablice kwot LA28 i kalendarze.
-- Jeździectwo dostaje poddyscypliny. Można uruchomić ponownie.
-- Źródła: systemy kwalifikacji FEI, FIE i IFAF dla LA28; wyniki MŚ 2026 (Akwizgran, Düsseldorf).

insert into public.dyscypliny (slug, nazwa, nadrzedna_id, kolejnosc)
select v.slug, v.nazwa, j.id, v.kol
from (values ('ujezdzenie', 'Ujeżdżenie', 1), ('wkkw', 'WKKW', 2), ('skoki-przez-przeszkody', 'Skoki przez przeszkody', 3)) as v(slug, nazwa, kol)
cross join (select id from public.dyscypliny where slug = 'jezdziectwo') j
on conflict (slug) do update set nadrzedna_id = excluded.nadrzedna_id, nazwa = excluded.nazwa;

update public.dyscypliny set opis_kafla = v.opis from (values
  ('jezdziectwo', 'Ujeżdżenie, WKKW, skoki przez przeszkody'),
  ('ujezdzenie', 'Drużyny i indywidualnie · grupa C to szansa Polski'),
  ('wkkw', 'Drużyny i indywidualnie · grupa C to szansa Polski'),
  ('skoki-przez-przeszkody', 'Drużyny i indywidualnie · grupa C to szansa Polski'),
  ('szermierka', 'Floret, szpada, szabla · rankingi FIE od 04.2027'),
  ('flag-football', 'Kobiety i mężczyźni · 6 drużyn')
) as v(slug, opis) where dyscypliny.slug = v.slug;

insert into public.konkurencje (dyscyplina_id, slug, nazwa, plec, miejsc, data_startu, opis, algorytm)
